package saver

import (
	"context"
	"testing"
)

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	m := &MemStore{}
	_ = Save(ctx, m, "id", "a", "b")
	if m.Puts() != 1 {
		t.Fatalf("Save with a cancelled context made %d Put calls, want 1", m.Puts())
	}
}
